import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"25、【無妄】 震下乾上","description":"周易尚氏學 - 25、【無妄】 震下乾上","frontmatter":{"title":"25、【無妄】 震下乾上","description":"周易尚氏學 - 25、【無妄】 震下乾上"},"headers":[],"relativePath":"classics/shangshi/030.md","filePath":"classics/shangshi/030.md"}'),s={name:"classics/shangshi/030.md"};function t(h,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_25、【無妄】-震下乾上" tabindex="-1">25、【無妄】 震下乾上 <a class="header-anchor" href="#_25、【無妄】-震下乾上" aria-label="Permalink to “25、【無妄】 震下乾上”">​</a></h1><p>震巽為草木為禾稼。下艮為火。故焦京王充皆以無望為大旱之卦。而乾為年。巽為人。年收失望。故曰無妄。元亨者。謂乾元通也。初當位。前臨重陰。五中正。故乾元以通。利貞者。利於貞定也。正亦定也。匪正謂三上。三上不當位。妄動。故有眚。眚病也。巽為疾病。其匪正有眚者。言不能貞定而躁動。即有眚也。不利有攸往。仍以動為戒也。震為決躁。躁動於內。外與剛健遇。必無幸矣。故曰不利有攸往。妄釋文雲。馬鄭玉肅皆作望。謂無所希望也。按此訓最古。史記春申君傳雲。世有毋望之福。又有毋望之禍。今君處毋望之世。事毋望之主。是自戰國即讀為望。作毋亡。妄古文妄之省。王陶廬雲。妄望同音相借。大戴禮文王篇故得望譽。望譽即妄譽。史遷受易於楊何。固無誤也。又按雜卦雲。無妄災也。故太玄擬無妄為去。漢書谷永傳。遭無妄之卦運。應劭雲。天必先雲而後雷。雷而後雨。今無雲而雷。無妄者無所望也。萬物無所望於天。災異之最大者也。後漢崔篆傳。值無妄之世。王充論衡。易無妄之應。水旱之至。蔡邕鄧皇后溢議。消無妄之運。舉兩漢之人。無作虛妄及失妄解者。無妄猶孟子所謂不虞也。六爻爻辭皆不虞之事。又無妄災也。以艮火象失傳之故。皆莫知災之自來。而焦京以無妄為大旱。易林屢見。詳焦氏易詁之卦。其故自荀虞莫明矣。卞斌雲。匪正宜作匪百。經無作正者。虞翻知巽為禾稼。而不知艮火象。故不知大旱之義。斥京氏為非。詁為亡失。不亡失則卦吉矣。然何以解於雜卦之無妄災及家傳。象傳曰。無妄之往何之矣。天命不右行矣哉。無妄若為吉卦。而曰天命不右。曰無所往。有是理乎。虞翻最忌鄭學。鄭作望故駁之。其所謂俗儒。殆即指鄭。後崔憬何妥競作虛妄解。益與傳背。世豈有忠信之人。天命不右。往無所合者哉。害理亂道。莫斯為甚。</p><p>彖曰。無妄。剛自外來。而為主於內。動而健。剛中而應。大亨以正。天之命也。其匪正有音。不利有攸往。無妄之往。何之矣。天命不佑。行矣哉。</p><p>震為主謂初也。先儒謂遁上來初。故曰自外來。震為躁卦。躁動於內。而外遇乾剛。故所之不合。五剛中。二有應。故曰剛中而應。大亨者。元亨也。以正者。利貞也。元亨利貞。循環來往。天命固如斯也。乾為天。巽為命也。臨傳雲。大亨以正。天之道也。天命與天道同也。故時當元亨而動。時當利貞。即不宜動。不宜動而強動。違天者也。違天而行。天所不福。右福也。何之者。言時值無望。無往而可也。蓋易之旨。陽剛不宜在外。在外則氣窮。有陽九之戶（加九？）。故卦辭以行為戒。以貞定為主。</p><p>象曰。天下雷行。物與無妄。先王以茂對時育萬物。</p><p>與舉也。天下雷行。萬物震恐。舉失其求望。茂與懋通。勉也。對答也。言因雷而勉答大威。傅亮文雲。只服住命。茂對天休。潘岳秋興賦。覽花蒔時之育兮。是茂對連文。時育連文。古讀如是。釋文作茂對時。非也。艮為時。震巽皆為草莽。而震為生。故曰時育萬物。即嚴畏天命。順時育物也。象有以相反為義者。如蠱曰振民育德。剝曰上以厚下安宅。明夷曰用晦而明。及此皆是也。虞仲翔不知此旨。據象言時育。證萬物皆死之非。審如是也。將蠱曰振育。亦可謂之不蠱。剝曰安宅。亦可謂之非剝。尚可通乎。</p><p>初九。無妄。往吉。</p><p>陽遇陰則通。故往吉。</p><h3 id="象曰。無妄之往。得志也。" tabindex="-1">象曰。無妄之往。得志也。 <a class="header-anchor" href="#象曰。無妄之往。得志也。" aria-label="Permalink to “象曰。無妄之往。得志也。”">​</a></h3><p>得志謂往遇二陰也。大畜九三雲。上合志。渙九二雲。得願。上皆無應。皆以前遇二陰。虞翻不知此為易不刊之定理。命四爻變陰。初得應釋得志。清儒從之。訛誤至今。</p><p>六二。不耕穫，不菑畲，則利有攸往。</p><p>獲悅文刈谷也。時小雅於此苗（中　）畝。蔬苗（中　）災也。始災殺其草木也，故說文雲。不耕田也。畬文三歲治田。時周頌。如何新畬。傳一歲曰畜。二歲曰新田。三歲日畬。爾雅同。獨鄭康成及虞翻謂田二歲曰畬。皆以在二爻豈知詩明曰新畬。是第一年苗（中　）田。第二年便為新田。然尚未柔和也。故第三年為畬田。觀詩不曰畬新。而曰新畬。鄭虞誤也。蓋二居艮震之間。震為耕為苗（中　）乃前遇艮。艮止。故不耕不苗。艮手為獲。艮成終。為畬。不耕而獲。不苗（中　）而畬。為必無望之事。故象以未富為釋。據坊記引則為兇字。又據說文引畬下多田字。段玉裁以為即兇之形訛字。然則則為兇字無疑。乃王注謂不耕而獲。不苗（中　）而畬。只代終。不造始。臣道固如是也。故利往。如王詁是亦獲亦畬也。與象未富之義不合。按易林無妄之訟雲。不耕而獲。家食不給。謂既不耕。獲必無得。故家食不給。讀雖與王同。而義則與小象不背矣。又禮坊記引此鄭彼注云言必先耕乃得獲。先苗（中　）乃得畬。安有無事而取利者乎。皆正詁。宜從。二有應。故利往。此自為一義。與上二句不相屬。與困彖同。</p><h3 id="象曰。不耕穫。未富也。" tabindex="-1">象曰。不耕穫。未富也。 <a class="header-anchor" href="#象曰。不耕穫。未富也。" aria-label="Permalink to “象曰。不耕穫。未富也。”">​</a></h3><p>六三。無妄之災。或繫之牛。行人之得。邑人之災。</p><p>無妄之災。猶不虞之災也。艮為牛。象失傳。詳焦氏易詁補遺。糞為系。故或繫之牛。震為行為人。巽為盜。故行人之得。艮為邑。良火故曰災。言或繫之牛。被行人牽去。居者反有盜嫌。遭詰捕之禍也。爻辭取象。神妙已極。乃自艮牛民火象失傳。自虞翻以來。皆用卦變。致妙用全失。蓋三不當位。而巽伏為盜。象失傳。詳焦氏易詁補遺故有是象。災之無妄。莫過於是。</p><h3 id="象曰。行人得牛。邑人災也。" tabindex="-1">象曰。行人得牛。邑人災也。 <a class="header-anchor" href="#象曰。行人得牛。邑人災也。" aria-label="Permalink to “象曰。行人得牛。邑人災也。”">​</a></h3><p>九四。可貞。無咎。</p><p>陽遇陽則窒。下又無應。不宜於動。故曰可貞。貞定也。然得重陰履之。故亦無咎。</p><h3 id="象曰。可貞無咎。固有之也。" tabindex="-1">象曰。可貞無咎。固有之也。 <a class="header-anchor" href="#象曰。可貞無咎。固有之也。" aria-label="Permalink to “象曰。可貞無咎。固有之也。”">​</a></h3><p>固有即謂二陰。虞翻亦用卦變說之。非。</p><p>九五。無安之症。勿藥有喜。</p><p>巽為疾。為草莽。故為藥。無妄之疾。言疾之愈已失望。乃勿藥而愈。其喜可知。五應在二。震為笑樂。故有喜也。勿藥者。言巽藥為艮為所焚也。</p><h3 id="象曰。無妄之藥。不可試也。" tabindex="-1">象曰。無妄之藥。不可試也。 <a class="header-anchor" href="#象曰。無妄之藥。不可試也。" aria-label="Permalink to “象曰。無妄之藥。不可試也。”">​</a></h3><p>不可試。言此為事之偶然。非所期望。不可嘗試。蓋五雖當位有應。然承乘皆陽。未為全吉。</p><p>上九。無安。行有眚。無攸利。</p><p>上應在三。巽為疾病。為眚。為利。然四五遇敵。故行有眚而無所利也。</p><h3 id="象曰。無妾之行。窮之災也。" tabindex="-1">象曰。無妾之行。窮之災也。 <a class="header-anchor" href="#象曰。無妾之行。窮之災也。" aria-label="Permalink to “象曰。無妾之行。窮之災也。”">​</a></h3>',27)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
